<script setup>
import { ref } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import Layout from '@/Layouts/ProviderLayout.vue';
defineProps({applications:Array,requirements:{type:Object,default:()=>({})}});
const detailLabels={applicantType:'Applicant type',businessName:'Registered business',relationship:'Ownership / authority',serviceCategory:'Service category',skills:'Skills and qualifications',experienceYears:'Years of experience'};
const titles={spaces:'Landlord / property merchant',haul:'Vehicle owner',raketeer:'Freelance service provider'};
const active=ref(null); const form=useForm({version:null,status:'approved',reviewNote:''});
function review(item,status){active.value=item;form.version=item.application?.version||null;form.clearErrors();form.status=status;form.reviewNote='';}
function submit(){form.post(`/admin/approvals/${active.value.userId}/${active.value.service}`,{preserveScroll:true,onSuccess:()=>active.value=null});}
</script>
<template><Layout><Head title="Review provider applications"/><main id="provider-main" class="provider-onboarding"><p class="workspace-kicker">Administration</p><h1>Provider applications</h1><p>Review each role independently. Supporting documents are private.</p><div v-if="!applications.length" class="workspace-empty"><h2>All caught up.</h2><p>No provider applications are waiting for review.</p></div><article v-for="item in applications" :key="item.userId+item.service" class="application-review"><div class="role-title"><h2>{{ item.application?.displayName || item.name }}</h2><span class="availability-tag draft">{{ titles[item.service] }}</span></div><p>{{ item.name }} · {{ item.email }}</p><template v-if="item.application"><dl><dt>Phone</dt><dd>{{ item.application.phone }}</dd><dt>Primary area</dt><dd>{{ item.application.area }}</dd><dt>Offering</dt><dd>{{ item.application.description }}</dd></dl><dl><template v-for="(label,key) in detailLabels" :key="key"><template v-if="item.application.details?.[key] != null && item.application.details[key] !== ''"><dt>{{ label }}</dt><dd>{{ item.application.details[key] }}</dd></template></template></dl><div class="review-documents"><a v-for="doc in item.application.documents" :key="doc.url" :href="doc.url" class="document-link">{{ requirements[item.service]?.[doc.type]?.label || 'Supporting document' }} · {{ doc.name }} ↗ <span v-if="doc.reference"> · {{ doc.reference }}</span><span v-if="doc.expiresAt"> · Expires {{ doc.expiresAt }}</span></a></div></template><p v-else class="role-notice">This older request has no supporting details. The user must complete the application before approval.</p><div class="actions"><button v-if="item.application" class="button primary" @click="review(item,'approved')">Approve role</button><button class="button" @click="review(item,'rejected')">Request an update</button></div><form v-if="active?.userId===item.userId&&active?.service===item.service" class="review-decision" @submit.prevent="submit"><h3>{{ form.status==='approved'?'Confirm approval':'Explain what needs updating' }}</h3><label>Review note {{ form.status==='approved'?'(optional)':'' }}<textarea v-model="form.reviewNote" :required="form.status==='rejected'" maxlength="2000" rows="3"/></label><p v-for="(error,key) in form.errors" :key="key" class="error" role="alert">{{ error }}</p><div class="actions"><button class="button primary" :disabled="form.processing">{{ form.processing?'Saving…':'Confirm decision' }}</button><button type="button" class="button" :disabled="form.processing" @click="active=null">Cancel</button></div></form></article></main></Layout></template>
